from math import ceil, log, floor, sqrt, gcd
for _ in range(int(input())):
	n = int(input())
	l = list(map(int, input().split()))
	f = {}
	for i in l:
		try:
			f[i] += 1
		except:
			f[i] = 1
	if max(f.values()) > n // 2 or len(set(l)) <= 2:
		print('NO')
	else:
		print('YES')
		l.sort()
		print(*l)
		print(*l[n // 2:] + l[:n // 2])
